//! Cargo-driven `certmgr.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is certmgr-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("certmgr-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "engine:c:cpprt", "import:cryptui", "import:crypt32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "engine:oldnames", "import:kernel32_vista", "engine:pseh", "engine:chkstk"],
        "x86_64" => &["body", "engine:uuid", "engine:c:cpprt", "import:cryptui", "import:crypt32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "engine:oldnames", "import:kernel32_vista", "engine:pseh"],
        "aarch64" => &["body", "engine:uuid", "engine:c:cpprt", "import:cryptui", "import:crypt32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "engine:oldnames", "import:kernel32_vista", "engine:pseh", "engine:chkstk"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/mscutils/certmgr",
        "base/applications/mscutils/certmgr",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("certmgr-rust")
        .c_from_compile_db("certmgr_shims", &["base/applications/mscutils/certmgr/rust_cohab_stub.cpp"])
        .rc("base/applications/mscutils/certmgr/certmgr.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("dll/win32/cryptui/cryptui.spec", "cryptui.dll", "cryptui")
        .import_lib("dll/win32/crypt32/crypt32.spec", "crypt32.dll", "crypt32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
